TEST(LibraryScanControllerTest, AnalysisCanBeCancelledAndRestarted) {
    LibraryScanController controller;
    int cancels = 0;
    QObject::connect(&controller, &LibraryScanController::cancelAnalysisRequested, [&] { ++cancels; });
    controller.onAnalysisActive(true);
    controller.cancel();
    EXPECT_EQ(1, cancels);
    controller.onAnalysisActive(false);
    EXPECT_FALSE(controller.isActive());
    EXPECT_EQ(0, controller.progress());
    controller.start();
    EXPECT_TRUE(controller.isActive());
    EXPECT_FALSE(controller.isCancelling());
}

